friends = {"Ali": ["Sara", "Bilal"], "Sara": ["Ali", "Hina"], "Bilal": ["Ali", "Hina", "Omar"], "Hina": ["Sara", "Bilal", "Zara"], "Omar": ["Bilal"], "Zara": ["Hina"]}
start = "Ali"

def bfs():
    distance = {start: 0}
    queue = [start]                          # enqueue the start node
    while queue:
        person = queue.pop(0)                # dequeue from the front
        print("Visit", person, "- degree", distance[person])
        for friend in friends[person]:
            if friend not in distance:       # not visited yet
                distance[friend] = distance[person] + 1
                queue.append(friend)

if start in friends:
    bfs()
else:
    print(start, "is not in the network")
